//! A persistent (immutable) vector, mirroring the observable behavior of
//! `immer::vector<T>`: every mutating operation returns a new vector and
//! leaves the original unchanged.

use std::rc::Rc;

/// Persistent vector with value semantics, like `immer::vector<T>`.
///
/// Cheap to clone (the underlying storage is shared); `push_back`
/// produces a new vector without modifying `self`.
pub struct Vector<T> {
    data: Rc<Vec<T>>,
}

impl<T> Vector<T> {
    /// Creates an empty vector.
    pub fn new() -> Self {
        Vector {
            data: Rc::new(Vec::new()),
        }
    }

    /// Number of elements in the vector.
    pub fn size(&self) -> usize {
        self.data.len()
    }

    /// Returns a new vector with `value` appended; `self` is unchanged.
    pub fn push_back(&self, value: T) -> Self
    where
        T: Clone,
    {
        let mut next = (*self.data).clone();
        next.push(value);
        Vector {
            data: Rc::new(next),
        }
    }

    /// Iterates over the elements in order.
    pub fn iter(&self) -> std::slice::Iter<'_, T> {
        self.data.iter()
    }
}

impl<T> Default for Vector<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Clone for Vector<T> {
    fn clone(&self) -> Self {
        Vector {
            data: Rc::clone(&self.data),
        }
    }
}

impl<T> std::ops::Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &Self::Output {
        &self.data[index]
    }
}

impl<'a, T> IntoIterator for &'a Vector<T> {
    type Item = &'a T;
    type IntoIter = std::slice::Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

