//! Port of /workspace/dataset/immer/tests/test11.cpp.
//!
//! Builds a persistent vector of `1..=n`, prints its sum, then builds a
//! second vector with each element doubled and prints that sum.

#[path = "src/lib.rs"]
mod immer;

use immer::Vector;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i32 = if args.len() > 1 {
        args[1].parse().expect("stoi")
    } else {
        11
    };

    let mut v = Vector::<i32>::new();
    for i in 0..n {
        v = v.push_back(i + 1);
    }

    let mut sum: i32 = 0;
    for x in &v {
        sum += *x;
    }

    println!("{}", sum);

    let mut v2 = Vector::<i32>::new();
    for i in 0..v.size() {
        v2 = v2.push_back(v[i] * 2);
    }

    sum = 0;
    for x in &v2 {
        sum += *x;
    }

    println!("{}", sum);
}

